package core

import (
	"fmt"
	"strings"
	"unicode"
)

// LineItem is one invoice line: Qty units of SKU at Unit each.
type LineItem struct {
	SKU      string
	Qty      int64
	Unit     Money
	Category string
}

// Gross returns the line's price before discount and tax.
func (l LineItem) Gross() Money {
	return Money(l.Qty) * l.Unit
}

// Invoice is a customer's invoice in one currency.
type Invoice struct {
	ID       string
	Customer string
	Currency string
	Lines    []LineItem
}

// Subtotal returns the sum of the lines' gross prices.
func (inv Invoice) Subtotal() Money {
	var sum Money
	for _, l := range inv.Lines {
		sum += l.Gross()
	}
	return sum
}

// Error is a validation error. Line is the 1-based index of the line at fault, or 0
// for the invoice's own fields.
type Error struct {
	Line int
	Msg  string
}

func (e *Error) Error() string {
	if e.Line == 0 {
		return "invoice: " + e.Msg
	}
	return fmt.Sprintf("invoice: line %d: %s", e.Line, e.Msg)
}

// Validate reports the first rule inv breaks, as an *Error, or nil.
func (inv Invoice) Validate() error {
	switch {
	case !isToken(inv.ID):
		return &Error{Msg: fmt.Sprintf("invalid ID %q", inv.ID)}
	case strings.TrimSpace(inv.Customer) == "":
		return &Error{Msg: "missing customer"}
	case len(inv.Currency) != 3 || strings.Trim(inv.Currency, "ABCDEFGHIJKLMNOPQRSTUVWXYZ") != "":
		return &Error{Msg: fmt.Sprintf("invalid currency %q", inv.Currency)}
	case len(inv.Lines) == 0:
		return &Error{Msg: "no lines"}
	}
	seen := map[string]bool{}
	for i, l := range inv.Lines {
		fail := func(format string, args ...any) error {
			return &Error{Line: i + 1, Msg: fmt.Sprintf(format, args...)}
		}
		switch {
		case !isToken(l.SKU):
			return fail("invalid SKU %q", l.SKU)
		case seen[l.SKU]:
			return fail("repeated SKU %q", l.SKU)
		case l.Qty < 1:
			return fail("quantity %d is not positive", l.Qty)
		case l.Unit < 0:
			return fail("negative unit price %s", l.Unit)
		case l.Category == "" || strings.Trim(l.Category, "abcdefghijklmnopqrstuvwxyz0123456789-") != "":
			return fail("invalid category %q", l.Category)
		}
		seen[l.SKU] = true
	}
	return nil
}

// isToken reports whether s is nonempty and has no whitespace.
func isToken(s string) bool {
	return s != "" && !strings.ContainsFunc(s, unicode.IsSpace)
}

reference.core/money.go:
// Package core holds the invoice library's money type and data model.
package core

import (
	"fmt"
	"math"
	"math/big"
	"strings"
)

// Money is an amount in cents.
type Money int64

// ParseMoney parses a decimal amount such as "12.50", "-3" or "0.5".
func ParseMoney(s string) (Money, error) {
	digits, negative := strings.CutPrefix(s, "-")
	whole, frac, dotted := strings.Cut(digits, ".")
	if !isDigits(whole) || dotted && (!isDigits(frac) || len(frac) > 2) {
		return 0, fmt.Errorf("core: invalid amount %q", s)
	}
	cents, ok := scaled(whole, frac, 2)
	if !ok || !negative && cents > math.MaxInt64 || cents > math.MaxInt64+1 {
		return 0, fmt.Errorf("core: amount %q out of range", s)
	}
	if negative {
		return Money(-cents), nil
	}
	return Money(cents), nil
}

// String formats m with two decimals, such as "12.50" or "-0.05".
func (m Money) String() string {
	sign, cents := "", uint64(m)
	if m < 0 {
		sign, cents = "-", -cents
	}
	return fmt.Sprintf("%s%d.%02d", sign, cents/100, cents%100)
}

// Rate is a nonnegative factor in millionths: 1000000 is 1 and 82500 is 8.25%.
type Rate int64

// ParseRate parses a decimal factor such as "0.9137" or a percentage such as "8.25%".
func ParseRate(s string) (Rate, error) {
	number, percent := strings.CutSuffix(s, "%")
	whole, frac, dotted := strings.Cut(number, ".")
	places := 6
	if percent {
		places = 4
	}
	if !isDigits(whole) || dotted && (!isDigits(frac) || len(frac) > places) {
		return 0, fmt.Errorf("core: invalid rate %q", s)
	}
	millionths, ok := scaled(whole, frac, places)
	if !ok || millionths > math.MaxInt64 {
		return 0, fmt.Errorf("core: rate %q out of range", s)
	}
	return Rate(millionths), nil
}

// String formats r as a percentage with at most four decimals, such as "8.25%".
func (r Rate) String() string {
	s := fmt.Sprintf("%d.%04d", int64(r)/10_000, int64(r)%10_000)
	return strings.TrimSuffix(strings.TrimRight(s, "0"), ".") + "%"
}

// scaled returns whole.frac times 10^places; frac has at most places digits.
func scaled(whole, frac string, places int) (uint64, bool) {
	var n uint64
	for _, c := range whole + frac + strings.Repeat("0", places-len(frac)) {
		if n > (math.MaxUint64-9)/10 {
			return 0, false
		}
		n = n*10 + uint64(c-'0')
	}
	return n, true
}

func isDigits(s string) bool {
	return s != "" && strings.Trim(s, "0123456789") == ""
}

// MulRate returns m times r, rounded to the cent with halves away from zero.
func (m Money) MulRate(r Rate) Money {
	product := new(big.Int).Mul(big.NewInt(int64(m)), big.NewInt(int64(r)))
	return Money(divRound(product, big.NewInt(1_000_000)))
}

// DivRound returns a divided by b, rounded to the nearest integer with halves away
// from zero. It panics when b is 0.
func DivRound(a, b int64) int64 {
	if b == 0 {
		panic("core: DivRound by zero")
	}
	return divRound(big.NewInt(a), big.NewInt(b))
}

func divRound(a, b *big.Int) int64 {
	q, r := new(big.Int).QuoRem(a, b, new(big.Int))
	// Round away from zero when the remainder is at least half the divisor.
	if twice := new(big.Int).Lsh(r.Abs(r), 1); twice.Cmp(new(big.Int).Abs(b)) >= 0 {
		q.Add(q, big.NewInt(int64(a.Sign()*b.Sign())))
	}
	return q.Int64()
}

