// Package discount parses discount rules and applies them to invoice lines.
package discount

import (
	"errors"
	"fmt"
	"strconv"
	"strings"

	"invoice/core"
)

// Rule is one discount rule.
type Rule struct {
	kind      string     // "percent", "tier", "bundle" or "off"
	target    string     // the lines' category (percent, tier) or SKU (bundle, off)
	tiers     []tier     // percent: one tier; tier: quantities in increasing order
	cap       core.Money // percent and tier: the most taken off a line, or 0 for no cap
	buy, free int64      // bundle: each buy paid units earn free units
	amount    core.Money // off: taken off each unit
}

// tier takes rate off lines of at least qty units.
type tier struct {
	qty  int64
	rate core.Rate
}

// Error is a syntax error at a 1-based line of the rules text.
type Error struct {
	Line int
	Msg  string
}

func (e *Error) Error() string {
	return fmt.Sprintf("discount: line %d: %s", e.Line, e.Msg)
}

// ParseRules parses discount rules, one per line.
func ParseRules(text string) ([]Rule, error) {
	var rules []Rule
	for i, line := range strings.Split(text, "\n") {
		line = strings.Trim(line, " \t\r")
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		rule, err := parseRule(strings.Fields(line))
		if err != nil {
			return nil, &Error{Line: i + 1, Msg: err.Error()}
		}
		rules = append(rules, rule)
	}
	return rules, nil
}

func parseRule(f []string) (Rule, error) {
	invalid := fmt.Errorf("invalid rule %q", strings.Join(f, " "))
	if len(f) < 3 {
		return Rule{}, invalid
	}
	r, args := Rule{kind: f[0], target: f[1]}, f[2:]
	var err error
	switch r.kind {
	case "percent", "tier":
		if n := len(args); n >= 3 && args[n-2] == "cap" {
			if r.cap, err = core.ParseMoney(args[n-1]); err != nil || r.cap <= 0 {
				return Rule{}, fmt.Errorf("invalid cap %q", args[n-1])
			}
			args = args[:n-2]
		}
		if r.kind == "percent" {
			r.tiers, err = percent(args)
		} else {
			r.tiers, err = tiers(args)
		}
	case "bundle":
		if len(args) != 2 {
			return Rule{}, invalid
		}
		if r.buy, err = count(args[0]); err == nil {
			r.free, err = count(args[1])
		}
	case "off":
		if len(args) != 1 {
			return Rule{}, invalid
		}
		if r.amount, err = core.ParseMoney(args[0]); err == nil && r.amount <= 0 {
			err = fmt.Errorf("amount %s is not positive", args[0])
		}
	default:
		return Rule{}, invalid
	}
	return r, err
}

// percent parses "<rate> [min <qty>]" as a single tier.
func percent(args []string) ([]tier, error) {
	t := tier{qty: 1}
	var err error
	switch {
	case len(args) == 3 && args[1] == "min":
		if t.qty, err = count(args[2]); err != nil {
			return nil, err
		}
	case len(args) != 1:
		return nil, fmt.Errorf("invalid percent rule %q", strings.Join(args, " "))
	}
	t.rate, err = share(args[0])
	return []tier{t}, err
}

// tiers parses one or more "<qty>:<rate>" with increasing quantities.
func tiers(args []string) ([]tier, error) {
	if len(args) == 0 {
		return nil, errors.New("no tiers")
	}
	var out []tier
	for _, arg := range args {
		qty, rate, ok := strings.Cut(arg, ":")
		if !ok {
			return nil, fmt.Errorf("invalid tier %q", arg)
		}
		var t tier
		var err error
		if t.qty, err = count(qty); err != nil {
			return nil, err
		}
		if t.rate, err = share(rate); err != nil {
			return nil, err
		}
		if len(out) > 0 && t.qty <= out[len(out)-1].qty {
			return nil, fmt.Errorf("tier %q does not raise the quantity", arg)
		}
		out = append(out, t)
	}
	return out, nil
}

// share parses a rate of at most 100%.
func share(s string) (core.Rate, error) {
	r, err := core.ParseRate(s)
	if err == nil && r > 1_000_000 {
		err = fmt.Errorf("rate %s is above 100%%", s)
	}
	return r, err
}

// count parses a positive decimal count.
func count(s string) (int64, error) {
	n, err := strconv.ParseInt(s, 10, 64)
	if err != nil || n < 1 || strings.Trim(s, "0123456789") != "" {
		return 0, fmt.Errorf("invalid count %q", s)
	}
	return n, nil
}

// String formats r as ParseRules reads it.
func (r Rule) String() string {
	f := []string{r.kind, r.target}
	switch r.kind {
	case "percent":
		f = append(f, r.tiers[0].rate.String())
		if r.tiers[0].qty > 1 {
			f = append(f, "min", strconv.FormatInt(r.tiers[0].qty, 10))
		}
	case "tier":
		for _, t := range r.tiers {
			f = append(f, fmt.Sprintf("%d:%s", t.qty, t.rate))
		}
	case "bundle":
		f = append(f, strconv.FormatInt(r.buy, 10), strconv.FormatInt(r.free, 10))
	case "off":
		f = append(f, r.amount.String())
	}
	if r.cap > 0 {
		f = append(f, "cap", r.cap.String())
	}
	return strings.Join(f, " ")
}

// off returns what r takes off item, or 0 when r does not apply.
func (r Rule) off(item core.LineItem) core.Money {
	var off core.Money
	switch {
	case r.kind == "bundle" && item.SKU == r.target:
		off = core.Money(item.Qty/(r.buy+r.free)*r.free) * item.Unit
	case r.kind == "off" && item.SKU == r.target:
		off = core.Money(item.Qty) * min(r.amount, item.Unit)
	case (r.kind == "percent" || r.kind == "tier") && item.Category == r.target:
		// The last tier the quantity reaches applies.
		for _, t := range r.tiers {
			if item.Qty >= t.qty {
				off = item.Gross().MulRate(t.rate)
			}
		}
	}
	if r.cap > 0 {
		off = min(off, r.cap)
	}
	return off
}

// Line applies the best of rules to item and returns the amount taken off: the
// largest discount of any one rule, or 0 when none applies.
func Line(item core.LineItem, rules []Rule) core.Money {
	var best core.Money
	for _, r := range rules {
		best = max(best, r.off(item))
	}
	return best
}

