// Package fx parses exchange-rate tables and converts money between currencies.
package fx

import (
	"fmt"
	"maps"
	"slices"
	"strings"

	"invoice/core"
)

// Table holds exchange rates between pairs of currencies.
type Table struct {
	rates map[[2]string]core.Rate // [from, to]: one from is worth rate to
	whole map[string]bool         // currencies without minor units
}

// Error is a syntax error at a 1-based line of the table text.
type Error struct {
	Line int
	Msg  string
}

func (e *Error) Error() string {
	return fmt.Sprintf("fx: line %d: %s", e.Line, e.Msg)
}

// ParseTable parses exchange rates, one currency pair per line.
func ParseTable(text string) (Table, error) {
	t := Table{rates: map[[2]string]core.Rate{}, whole: map[string]bool{}}
	for i, line := range strings.Split(text, "\n") {
		line = strings.Trim(line, " \t\r")
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if err := t.add(strings.Fields(line)); err != nil {
			return Table{}, &Error{Line: i + 1, Msg: err.Error()}
		}
	}
	return t, nil
}

// add adds one "FROM TO RATE" or "whole CODE" line, given as its fields.
func (t Table) add(f []string) error {
	if len(f) == 2 && f[0] == "whole" && isCode(f[1]) {
		if t.whole[f[1]] {
			return fmt.Errorf("repeated whole currency %s", f[1])
		}
		t.whole[f[1]] = true
		return nil
	}
	if len(f) != 3 || !isCode(f[0]) || !isCode(f[1]) || f[0] == f[1] {
		return fmt.Errorf("invalid line %q", strings.Join(f, " "))
	}
	_, there := t.rates[[2]string{f[0], f[1]}]
	_, back := t.rates[[2]string{f[1], f[0]}]
	if there || back {
		return fmt.Errorf("repeated pair %s %s", f[0], f[1])
	}
	rate, err := core.ParseRate(f[2])
	if err != nil || rate == 0 || strings.HasSuffix(f[2], "%") {
		return fmt.Errorf("invalid rate %q", f[2])
	}
	t.rates[[2]string{f[0], f[1]}] = rate
	return nil
}

func isCode(s string) bool {
	return len(s) == 3 && strings.Trim(s, "ABCDEFGHIJKLMNOPQRSTUVWXYZ") == ""
}

// Convert converts m from currency from to currency to, through the fewest listed
// pairs; of equally short routes it takes the alphabetically first. Each step rounds
// to the cent, or to whole units in a whole currency.
func (t Table) Convert(m core.Money, from, to string) (core.Money, error) {
	steps := t.distances(to)
	if _, ok := steps[from]; !ok {
		return 0, fmt.Errorf("fx: no rate from %s to %s", from, to)
	}
	for at := from; at != to; {
		// The first neighbour, alphabetically, one step closer to to.
		next := ""
		for _, c := range t.neighbours(at) {
			if n, ok := steps[c]; ok && n == steps[at]-1 {
				next = c
				break
			}
		}
		m, at = t.step(m, at, next), next
	}
	return m, nil
}

// distances returns each currency's number of steps to to, for those linked to it.
func (t Table) distances(to string) map[string]int {
	steps := map[string]int{to: 0}
	for queue := []string{to}; len(queue) > 0; queue = queue[1:] {
		for _, c := range t.neighbours(queue[0]) {
			if _, ok := steps[c]; !ok {
				steps[c] = steps[queue[0]] + 1
				queue = append(queue, c)
			}
		}
	}
	return steps
}

// neighbours returns the currencies paired with c, sorted.
func (t Table) neighbours(c string) []string {
	var out []string
	for pair := range t.rates {
		if pair[0] == c {
			out = append(out, pair[1])
		} else if pair[1] == c {
			out = append(out, pair[0])
		}
	}
	slices.Sort(out)
	return out
}

// step converts m by the pair listed between from and to, in either direction.
func (t Table) step(m core.Money, from, to string) core.Money {
	if r, ok := t.rates[[2]string{from, to}]; ok {
		m = m.MulRate(r)
	} else {
		m = core.Money(core.DivRound(int64(m)*1_000_000, int64(t.rates[[2]string{to, from}])))
	}
	if t.whole[to] {
		m = core.Money(core.DivRound(int64(m), 100) * 100)
	}
	return m
}

// String formats t as ParseTable reads it: the whole currencies, then the pairs, each
// sorted, with rates as decimals.
func (t Table) String() string {
	var b strings.Builder
	for _, c := range slices.Sorted(maps.Keys(t.whole)) {
		fmt.Fprintf(&b, "whole %s\n", c)
	}
	pairs := slices.SortedFunc(maps.Keys(t.rates), func(x, y [2]string) int {
		return strings.Compare(x[0]+x[1], y[0]+y[1])
	})
	for _, p := range pairs {
		r := t.rates[p]
		digits := strings.TrimRight(fmt.Sprintf("%d.%06d", int64(r)/1_000_000, int64(r)%1_000_000), "0")
		fmt.Fprintf(&b, "%s %s %s\n", p[0], p[1], strings.TrimSuffix(digits, "."))
	}
	return b.String()
}

reference.parse/parse.go:
// Package parse reads invoices from text.
package parse

import (
	"fmt"
	"strconv"
	"strings"

	"invoice/core"
)

// Error is a syntax error at a 1-based line of the invoice text.
type Error struct {
	Line int
	Msg  string
}

func (e *Error) Error() string {
	return fmt.Sprintf("parse: line %d: %s", e.Line, e.Msg)
}

// Parse reads an invoice from text. It returns a zero Invoice with a syntax *Error,
// or the invoice with its Validate error.
func Parse(text string) (core.Invoice, error) {
	var inv core.Invoice
	seen := map[string]bool{}
	for i, line := range strings.Split(text, "\n") {
		line = strings.Trim(uncomment(line), " \t\r")
		if line == "" {
			continue
		}
		fail := func(format string, args ...any) (core.Invoice, error) {
			return core.Invoice{}, &Error{Line: i + 1, Msg: fmt.Sprintf(format, args...)}
		}
		f := strings.Fields(line)
		header := map[string]*string{"invoice": &inv.ID, "customer": &inv.Customer, "currency": &inv.Currency}
		if field, ok := header[f[0]]; ok {
			switch {
			case seen[f[0]]:
				return fail("repeated %s", f[0])
			case len(f) == 1, f[0] != "customer" && len(f) != 2:
				return fail("invalid %s line", f[0])
			}
			seen[f[0]] = true
			*field = strings.Join(f[1:], " ")
			continue
		}
		if len(f) != 4 {
			return fail("item line needs SKU, quantity, unit price and category")
		}
		qty, err := strconv.ParseInt(f[1], 10, 64)
		if err != nil || strings.Trim(f[1], "0123456789") != "" {
			return fail("invalid quantity %q", f[1])
		}
		unit, err := core.ParseMoney(f[2])
		if err != nil {
			return fail("invalid unit price %q", f[2])
		}
		inv.Lines = append(inv.Lines, core.LineItem{SKU: f[0], Qty: qty, Unit: unit, Category: f[3]})
	}
	return inv, inv.Validate()
}

// uncomment drops a comment: a # at the start of the line or after a space or tab.
func uncomment(line string) string {
	for i := range len(line) {
		if line[i] == '#' && (i == 0 || line[i-1] == ' ' || line[i-1] == '\t') {
			return line[:i]
		}
	}
	return line
}

// Format writes inv as Parse reads it: the header lines, then one line per item.
func Format(inv core.Invoice) string {
	var b strings.Builder
	fmt.Fprintf(&b, "invoice %s\ncustomer %s\ncurrency %s\n", inv.ID, inv.Customer, inv.Currency)
	for _, l := range inv.Lines {
		fmt.Fprintf(&b, "%s %d %s %s\n", l.SKU, l.Qty, l.Unit, l.Category)
	}
	return b.String()
}

reference.render/render.go:
// Package render lays out plain-text tables.
package render

import (
	"strings"
	"unicode/utf8"
)

// Column is a table column: its title, whether its cells align right, and the most
// runes a cell line may show (0 for no limit).
type Column struct {
	Title string
	Right bool
	Max   int
}

// Table lays out rows under the columns' titles, then footer rows after a rule.
func Table(cols []Column, rows, footer [][]string) string {
	if len(cols) == 0 {
		return ""
	}
	titles := make([]string, len(cols))
	for i, c := range cols {
		titles[i] = c.Title
	}
	// Each row becomes one or more physical lines of fitted cells.
	var all [][][]string
	for _, row := range append(append([][]string{titles}, rows...), footer...) {
		all = append(all, physical(cols, row))
	}
	widths := make([]int, len(cols))
	for _, lines := range all {
		for _, line := range lines {
			for i, cell := range line {
				widths[i] = max(widths[i], utf8.RuneCountInString(cell))
			}
		}
	}
	rule := make([]string, len(cols))
	for i, w := range widths {
		rule[i] = strings.Repeat("-", w)
	}
	var b strings.Builder
	write := func(line []string) {
		cells := make([]string, len(cols))
		for i, c := range cols {
			pad := strings.Repeat(" ", widths[i]-utf8.RuneCountInString(line[i]))
			if c.Right {
				cells[i] = pad + line[i]
			} else {
				cells[i] = line[i] + pad
			}
		}
		b.WriteString(strings.TrimRight(strings.Join(cells, "  "), " ") + "\n")
	}
	section := func(group [][][]string) {
		for _, lines := range group {
			for _, line := range lines {
				write(line)
			}
		}
	}
	section(all[:1])
	write(rule)
	section(all[1 : 1+len(rows)])
	if len(footer) > 0 {
		write(rule)
		section(all[1+len(rows):])
	}
	return b.String()
}

// physical splits row's cells at newlines into lines with one cell per column,
// cutting cells longer than their column's Max.
func physical(cols []Column, row []string) [][]string {
	var lines [][]string
	for i, c := range cols {
		if i >= len(row) {
			break
		}
		for j, part := range strings.Split(row[i], "\n") {
			if j == len(lines) {
				lines = append(lines, make([]string, len(cols)))
			}
			if c.Max > 0 && utf8.RuneCountInString(part) > c.Max {
				part = string([]rune(part)[:c.Max-1]) + "…"
			}
			lines[j][i] = part
		}
	}
	if len(lines) == 0 {
		lines = append(lines, make([]string, len(cols)))
	}
	return lines
}

