// Package tax parses tax tables and taxes invoice lines.
package tax

import (
	"fmt"
	"maps"
	"slices"
	"strings"

	"invoice/core"
)

// Table holds tax rates by category, a default rate and exempt SKUs. The zero Table
// taxes nothing.
type Table struct {
	rates      map[string]rate
	fallback   core.Rate
	hasDefault bool
	exempt     map[string]bool
}

// rate is a category's rate. With split set, units priced above over pay above.
type rate struct {
	base, above core.Rate
	over        core.Money
	split       bool
}

// Error is a syntax error at a 1-based line of the table text.
type Error struct {
	Line int
	Msg  string
}

func (e *Error) Error() string {
	return fmt.Sprintf("tax: line %d: %s", e.Line, e.Msg)
}

// ParseTable parses a tax table, one entry per line.
func ParseTable(text string) (Table, error) {
	t := Table{rates: map[string]rate{}, exempt: map[string]bool{}}
	for i, line := range strings.Split(text, "\n") {
		line = strings.Trim(line, " \t\r")
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		if err := t.add(strings.Fields(line)); err != nil {
			return Table{}, &Error{Line: i + 1, Msg: err.Error()}
		}
	}
	return t, nil
}

// add adds one entry, given as its fields.
func (t *Table) add(f []string) error {
	var err error
	switch {
	case f[0] == "rate" && (len(f) == 3 || len(f) == 6 && f[3] == "over"):
		if _, ok := t.rates[f[1]]; ok {
			return fmt.Errorf("repeated category %q", f[1])
		}
		var r rate
		if r.base, err = core.ParseRate(f[2]); err != nil {
			return err
		}
		if len(f) == 6 {
			r.split = true
			if r.over, err = core.ParseMoney(f[4]); err != nil || r.over < 0 {
				return fmt.Errorf("invalid threshold %q", f[4])
			}
			if r.above, err = core.ParseRate(f[5]); err != nil {
				return err
			}
		}
		t.rates[f[1]] = r
		return nil
	case f[0] == "default" && len(f) == 2:
		if t.hasDefault {
			return fmt.Errorf("repeated default")
		}
		t.fallback, err = core.ParseRate(f[1])
		t.hasDefault = true
		return err
	case f[0] == "exempt" && len(f) == 2:
		if t.exempt[f[1]] {
			return fmt.Errorf("repeated exempt SKU %q", f[1])
		}
		t.exempt[f[1]] = true
		return nil
	}
	return fmt.Errorf("invalid entry %q", strings.Join(f, " "))
}

// Rate returns the rate Line applies to item.
func (t Table) Rate(item core.LineItem) core.Rate {
	if t.exempt[item.SKU] {
		return 0
	}
	r, ok := t.rates[item.Category]
	switch {
	case !ok:
		return t.fallback
	case r.split && item.Unit > r.over:
		return r.above
	}
	return r.base
}

// Line returns the tax on item when its price after discount is net: net at
// item's rate, rounded to the cent.
func (t Table) Line(item core.LineItem, net core.Money) core.Money {
	return net.MulRate(t.Rate(item))
}

// String formats t as ParseTable reads it: the default rate, then the categories,
// then the exempt SKUs, each sorted.
func (t Table) String() string {
	var b strings.Builder
	if t.hasDefault {
		fmt.Fprintf(&b, "default %s\n", t.fallback)
	}
	for _, category := range slices.Sorted(maps.Keys(t.rates)) {
		r := t.rates[category]
		fmt.Fprintf(&b, "rate %s %s", category, r.base)
		if r.split {
			fmt.Fprintf(&b, " over %s %s", r.over, r.above)
		}
		b.WriteByte('\n')
	}
	for _, sku := range slices.Sorted(maps.Keys(t.exempt)) {
		fmt.Fprintf(&b, "exempt %s\n", sku)
	}
	return b.String()
}

reference.totals.go:
package invoice

import (
	"invoice/core"
	"invoice/discount"
	"invoice/tax"
)

// Totals returns inv's summary with its discount, tax and total.
func Totals(inv core.Invoice, rules []discount.Rule, taxes tax.Table) Summary {
	s := Summarize(inv)
	for _, l := range inv.Lines {
		off, tx := price(l, rules, taxes)
		s.Discount += off
		s.Tax += tx
	}
	s.Total = s.Subtotal - s.Discount + s.Tax
	return s
}

// price returns the line's discount and its tax on the discounted price.
func price(l core.LineItem, rules []discount.Rule, taxes tax.Table) (off, tx core.Money) {
	off = discount.Line(l, rules)
	return off, taxes.Line(l, l.Gross()-off)
}

