func TestConvert(t *testing.T) {
	r := rates(t, "USD EUR 0.9137\nEUR GBP 0.8\nUSD CHF 0.9\nCHF GBP 0.85\nwhole JPY\nUSD JPY 151.234\nGBP SEK 13.5\n")
	for _, c := range []struct {
		m        core.Money
		from, to string
		want     core.Money
	}{
		{10000, "USD", "USD", 10000},
		{123, "XXX", "XXX", 123},
		{10000, "USD", "EUR", 9137},
		{9137, "EUR", "USD", 10000},
		{100, "EUR", "USD", 109},
		{-100, "EUR", "USD", -109},
		{1000, "USD", "JPY", 151200},
		{1003, "USD", "JPY", 151700},
		{151200, "JPY", "USD", 1000},
		{10000, "USD", "GBP", 7650},
		{10000, "EUR", "CHF", 9412},
		{10000, "USD", "SEK", 103275},
		{10000, "JPY", "CHF", 59},
	} {
		if got, err := r.Convert(c.m, c.from, c.to); err != nil || got != c.want {
			t.Errorf("Convert(%d, %s, %s) = %d, %v; want %d", c.m, c.from, c.to, got, err, c.want)
		}
	}
	for _, pair := range [][2]string{{"USD", "NOK"}, {"NOK", "USD"}, {"usd", "EUR"}} {
		if _, err := r.Convert(100, pair[0], pair[1]); err == nil {
			t.Errorf("Convert %s to %s succeeded", pair[0], pair[1])
