func TestTotals(t *testing.T) {
	got := invoice.Totals(cart(), rules(t, shop), table(t, taxes))
	// Per line: discount, then tax on the rest, rounded per line.
	// BK-1 3750: 375 off, 0% -> 0. MUG 2331: 666 off, 20% of 1665 -> 333.
	// PEN 225: 45 off, 20% of 180 -> 36. TEA 499: 0 off, 5% -> 24.95 -> 25.
	// CAR 11994: 1199.4 -> 1199 off, 20% of 10795 -> 2159. GIFT: exempt. COAT 12000: 6% -> 720.
	want := invoice.Summary{ID: "INV-9", Customer: "Acme Ltd", Subtotal: 32799, Discount: 2285, Tax: 3273, Total: 33787}
	if got != want {
		t.Errorf("Totals = %+v\nwant %+v", got, want)
	}
	// Tax is rounded per line, not on the sum: 2 x 2.5 cents.
	two := core.Invoice{ID: "I", Customer: "C", Currency: "USD", Lines: []core.LineItem{
		{SKU: "A", Qty: 1, Unit: 50, Category: "food"}, {SKU: "B", Qty: 1, Unit: 50, Category: "food"}}}
	if s := invoice.Totals(two, nil, table(t, taxes)); s.Tax != 6 || s.Total != 106 {
		t.Errorf("per-line rounding: %+v", s)
	}
	// Totals does not validate.
	if s := invoice.Totals(core.Invoice{Lines: two.Lines}, nil, tax.Table{}); s.Subtotal != 100 || s.Total != 100 {
		t.Errorf("unvalidated: %+v", s)
	}
}

