// amounts returns a statement's printed line amounts and its printed total.
func amounts(t *testing.T, statement string) ([]core.Money, core.Money) {
	t.Helper()
	lines := strings.Split(statement, "\n")
	var rules []int
	for i, line := range lines {
		if strings.HasPrefix(line, "---") {
			rules = append(rules, i)
		}
	}
	if len(rules) != 2 {
		t.Fatalf("statement has %d rules:\n%s", len(rules), statement)
	}
	last := func(line string) core.Money {
		f := strings.Fields(line)
		m, err := core.ParseMoney(f[len(f)-1])
		if err != nil {
			t.Fatalf("line %q: %v", line, err)
		}
		return m
	}
	var out []core.Money
	for _, line := range lines[rules[0]+1 : rules[1]] {
		out = append(out, last(line))
	}
	for _, line := range lines[rules[1]+1:] {
		if strings.HasPrefix(line, "Total ") {
			return out, last(line)
		}
	}
	t.Fatalf("no Total line:\n%s", statement)
	return nil, 0
}

func TestStatementAmountsSumToTotal(t *testing.T) {
	r, tt := rules(t, shop+"percent food 33.3333%\npercent clothing 7.77%\n"), table(t, taxes+"rate home 8.875%\n")
	invoices := []core.Invoice{cart(), valid(), one("MUG", 5, 1, "home")}
	odd := core.Invoice{ID: "ODD", Customer: "Odd", Currency: "USD"}
	for i := range 12 {
		odd.Lines = append(odd.Lines, core.LineItem{SKU: string(rune('A' + i)), Qty: int64(i%5 + 1), Unit: core.Money(97*i + 13),
			Category: []string{"food", "home", "toys", "clothing", "books"}[i%5]})
	}
	odd.Lines = append(odd.Lines, core.LineItem{SKU: "MUG", Qty: 8, Unit: 117, Category: "home"}, core.LineItem{SKU: "PEN", Qty: 3, Unit: 3, Category: "office"})
	invoices = append(invoices, odd)
	for _, inv := range invoices {
		s, text, err := invoice.Statement(inv, r, tt, fx.Table{}, inv.Currency)
		if err != nil {
			t.Fatalf("%s: %v", inv.ID, err)
		}
		lines, total := amounts(t, text)
		var sum core.Money
		for _, m := range lines {
			sum += m
		}
		if len(lines) != len(inv.Lines) || sum != total || total != s.Total {
			t.Errorf("%s: %d line amounts sum to %d; printed total %d, Summary total %d", inv.ID, len(lines), sum, total, s.Total)
		}
	}
}
